(()=>{
 const dialog=document.querySelector('#customer-dialog'),content=document.querySelector('#customer-content');if(!dialog||!content)return;
 let customer=null,csrf='',poll=null;
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const money=n=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(n||0);
 const status=s=>({pending_review_demo:'Chờ duyệt',pending_payment:'Chờ thanh toán',confirmed:'Đã duyệt',confirmed_demo:'Đã duyệt',rejected:'Không được duyệt',cancelled_demo:'Đã hủy'}[s]||s);
 const payment=s=>({not_paid:'Chưa thanh toán',unpaid:'Chưa thanh toán',paid:'Đã thanh toán',simulated_paid:'Đã thanh toán',failed:'Thanh toán chưa thành công'}[s]||'Chưa thanh toán');
 async function api(path,body){const r=await fetch('/api/customer'+path,{method:body?'POST':'GET',headers:{...(body?{'Content-Type':'application/json','X-CSRF-Token':csrf}:{})},body:body?JSON.stringify(body):undefined});let d;try{d=await r.json();}catch{throw Error('Không thể kết nối máy chủ.');}if(!r.ok)throw Error(d.error||'Yêu cầu chưa thực hiện được.');if(d.csrf)csrf=d.csrf;return d;}
 function showError(message){const box=content.querySelector('[data-customer-error]');if(box){box.hidden=false;box.textContent=message;}}
 function authForm(mode='login'){const register=mode==='register';content.innerHTML=`<p class="eyebrow">TRÀ JOURNEY · KHÁCH HÀNG</p><h2>${register?'Tạo tài khoản':'Đăng nhập'}</h2><p class="customer-muted">Quản lý booking, theo dõi thông báo và thanh toán đơn đã được duyệt.</p><form data-auth-form>${register?'<label>Họ và tên<input name="fullName" autocomplete="name" maxlength="80" required></label>':''}<label>Email<input name="email" type="email" autocomplete="email" maxlength="150" required></label>${register?'<label>Số điện thoại<input name="phone" type="tel" autocomplete="tel" placeholder="0xxxxxxxxx" required></label>':''}<label>Mật khẩu<input name="password" type="password" autocomplete="${register?'new-password':'current-password'}" minlength="${register?10:1}" required></label><p class="customer-error" data-customer-error hidden></p><button class="button full" type="submit">${register?'Tạo tài khoản':'Đăng nhập'}</button></form><button type="button" class="customer-link" data-switch>${register?'Đã có tài khoản? Đăng nhập':'Chưa có tài khoản? Tạo tài khoản'}</button>`;
  content.querySelector('[data-switch]').onclick=()=>authForm(register?'login':'register');content.querySelector('form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));try{const d=await api(register?'/register':'/login',data);customer=d.customer;csrf=d.csrf;window.customerUser=customer;await dashboard();}catch(x){showError(x.message);}};
 }
 function open(){dialog.showModal();if(customer)dashboard();else authForm();}
 document.querySelectorAll('[data-customer-open]').forEach(x=>x.addEventListener('click',open));document.querySelector('[data-customer-close]')?.addEventListener('click',()=>dialog.close());
 function openPayment(book){const ref=`TRJ|${book.code}|${book.depositVND}`;const qr=`https://api.qrserver.com/v1/create-qr-code/?size=220x220&margin=2&data=${encodeURIComponent(ref)}`;content.innerHTML=`<button type="button" class="customer-link" data-back>← Đơn của tôi</button><p class="eyebrow">THANH TOÁN ĐƠN HÀNG</p><h2>${esc(book.tourName)}</h2><p>Mã đơn <b>${esc(book.code)}</b></p><div class="payment-panel"><img class="payment-qr" src="${qr}" alt="Mã QR đơn ${esc(book.code)}"><div><span>Số tiền cần thanh toán</span><strong>${money(book.depositVND)}</strong><span>Nội dung thanh toán</span><b>${esc(book.code)}</b></div></div><p class="payment-disclosure">Đây là cổng xử lý thanh toán nội bộ. Không chuyển tiền thật qua mã QR này; hãy chọn kết quả giao dịch bên dưới.</p><div class="payment-actions"><button type="button" class="button" data-result="success">Thanh toán thành công</button><button type="button" class="outline" data-result="failure">Thanh toán thất bại</button></div><p class="customer-error" data-customer-error hidden></p>`;
  content.querySelector('[data-back]').onclick=dashboard;content.querySelectorAll('[data-result]').forEach(btn=>btn.onclick=async()=>{btn.disabled=true;try{await api(`/bookings/${encodeURIComponent(book.code)}/payment`,{outcome:btn.dataset.result});await dashboard();}catch(e){btn.disabled=false;showError(e.message);}});
 }
 async function dashboard(){try{const [orders,notices]=await Promise.all([api('/bookings'),api('/notifications')]);customer=window.customerUser||customer;const orderList=orders.items||[],noticeList=notices.items||[];content.innerHTML=`<div class="customer-head"><div><p class="eyebrow">TÀI KHOẢN KHÁCH HÀNG</p><h2>Xin chào, ${esc(customer?.fullName||'bạn')}</h2><p class="customer-muted">${esc(customer?.email||'')}</p></div><button type="button" class="outline" data-logout>Đăng xuất</button></div><section class="customer-section"><h3>Thông báo <span class="customer-count">${noticeList.length}</span></h3>${noticeList.length?noticeList.slice(0,8).map(n=>`<article class="customer-notice"><b>${n.status==='confirmed'?'Đơn đã được duyệt':n.status==='rejected'?'Đơn chưa được duyệt':n.status==='paid'?'Đã ghi nhận thanh toán':n.status==='failed'?'Thanh toán chưa thành công':'Cập nhật đơn hàng'}</b><span>${esc(n.tourName)} · ${esc(n.bookingCode)}</span>${n.reason?`<small>${esc(n.reason)}</small>`:''}<time>${new Date(n.at).toLocaleString('vi-VN')}</time></article>`).join(''):'<p class="customer-muted">Chưa có thông báo mới.</p>'}</section><section class="customer-section"><h3>Đơn booking của tôi <span class="customer-count">${orderList.length}</span></h3>${orderList.length?orderList.map(b=>`<article class="customer-order"><div class="customer-order-top"><div><span class="customer-order-code">${esc(b.code)}</span><h4>${esc(b.tourName)}</h4></div><span class="customer-status ${b.bookingStatus==='confirmed'?'is-approved':b.bookingStatus==='rejected'?'is-rejected':''}">${status(b.bookingStatus)}</span></div><p>Khởi hành ${esc(b.departureDate)} · ${esc(b.departureTime)} · ${b.seats} khách</p><div class="customer-order-bottom"><b>${money(b.totalVND)}</b><span>Thanh toán: ${payment(b.paymentStatus)}</span></div>${b.rejectionReason?`<p class="customer-muted">Lý do: ${esc(b.rejectionReason)}</p>`:''}${b.bookingStatus==='confirmed'&&b.paymentStatus!=='paid'?`<button class="button customer-pay" data-pay="${esc(b.code)}">${b.paymentStatus==='failed'?'Thử thanh toán lại':'Thanh toán'} · ${money(b.depositVND)}</button>`:''}</article>`).join(''):'<p class="customer-muted">Bạn chưa có đơn booking nào. Đăng nhập tài khoản này trước khi gửi yêu cầu đặt tour để đơn được lưu tại đây.</p>'}</section>`;
  content.querySelector('[data-logout]').onclick=async()=>{try{await api('/logout',{});}catch{}customer=null;csrf='';window.customerUser=null;document.querySelectorAll('[data-customer-open]').forEach(x=>x.textContent='Tài khoản');clearInterval(poll);authForm();};content.querySelectorAll('[data-pay]').forEach(b=>b.onclick=()=>{const orderList=orders.items||[];openPayment(orderList.find(x=>x.code===b.dataset.pay));});
 }catch(e){authForm();showError(e.message);}}
 window.openCustomerAccount=open;window.refreshCustomerDashboard=dashboard;
 api('/session').then(d=>{customer=d.customer;csrf=d.csrf;window.customerUser=customer;document.querySelectorAll('[data-customer-open]').forEach(x=>x.textContent=`${customer.fullName.split(' ')[0]} · Tài khoản`);if(dialog.open)dashboard();poll=setInterval(()=>{if(dialog.open&&customer)dashboard();},20000);}).catch(()=>{});
})();
